#[derive(Clone)]
pub struct AppState {
    event_bus: EventBus,
    tools: Vec<ToolDefinitionView>,
    workflows: Vec<WorkflowDefinitionView>,
    workflow_catalog: WorkflowCatalog,
    storage: PgStorage,
    tenant_id: TenantId,
}

impl AppState {
    pub fn new(
        storage: PgStorage,
        workflow_catalog: WorkflowCatalog,
        tenant_id: TenantId,
        event_bus: EventBus,
    ) -> Self {
        let tool_registry = bootstrap_default_tool_registry();
        let tools = tool_registry
            .list()
            .into_iter()
            .map(to_tool_definition_view)
            .collect();
        let workflows = workflow_catalog
            .descriptors()
            .into_iter()
            .map(|definition| WorkflowDefinitionView {
                kind: definition.kind,
                version: definition.version,
                summary: definition.summary,
                accepted_signals: definition
                    .accepted_signals
                    .into_iter()
                    .map(|signal| signal.as_str().to_string())
                    .collect(),
            })
            .collect();

        Self {
            event_bus,
            tools,
            workflows,
            workflow_catalog,
            storage,
            tenant_id,
        }
    }
}

