async fn retry_external_channel_action_runs(
    state: &AppState,
    integration_id: &str,
    now: DateTime<Utc>,
) -> std::result::Result<ExternalActionRetrySchedule, ApiError> {
    let rows = sqlx::query(
        r#"
        select id
        from external_action_runs
        where tenant_id = $1
          and requester_summary ->> 'channel_connection_id' = $2
          and external_request_id is null
          and confirmation_state in ('not_required', 'confirmed')
          and result_summary ->> 'status' in ('dispatch_blocked', 'dispatch_failed')
        order by updated_at desc
        limit 10
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let mut schedule = ExternalActionRetrySchedule::default();
    for row in rows {
        let action_id: String = row.get("id");
        let started =
            enqueue_external_action_dispatch_retry(state, integration_id, &action_id, now).await?;
        if schedule.workflow_execution.is_none() {
            schedule.workflow_execution = Some(started.execution.clone());
        }
        schedule.enqueued_tasks.extend(started.enqueued_tasks);
        schedule.affected_action_count += 1;
    }
    Ok(schedule)
}

async fn enqueue_external_action_dispatch_retry(
    state: &AppState,
    connection_id: &str,
    action_id: &str,
    now: DateTime<Utc>,
) -> std::result::Result<AdvanceWorkflowExecutionResponse, ApiError> {
    let workflow_execution =
        build_initial_external_action_dispatch_execution(state, connection_id, action_id, now)?;
    let initial_event =
        build_initial_external_action_dispatch_event(&workflow_execution, connection_id, action_id);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&workflow_execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        workflow_execution.id,
        WorkflowSignal::Start,
    )
    .await?;
    mark_external_action_retry_queued(state, action_id, &started, now).await?;
    Ok(started)
}

async fn mark_external_action_retry_queued(
    state: &AppState,
    action_id: &str,
    started: &AdvanceWorkflowExecutionResponse,
    now: DateTime<Utc>,
) -> std::result::Result<(), ApiError> {
    let task_ids: Vec<String> = started
        .enqueued_tasks
        .iter()
        .map(|task| task.id.to_string())
        .collect();
    let result_patch = json!({
        "status": "retry_queued",
        "retry": {
            "workflow_execution_id": started.execution.id,
            "workflow_stage": started.execution.stage,
            "task_ids": task_ids,
            "queue": "external_action",
            "queued_at": now,
        },
        "updated_at": now,
    });
    sqlx::query(
        r#"
        update external_action_runs
        set result_summary = result_summary || $3,
            failure_kind = null,
            updated_at = $4
        where tenant_id = $1 and id = $2
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(action_id)
    .bind(result_patch)
    .bind(now)
    .execute(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;
    Ok(())
}

async fn load_external_channel_audit_items(
    state: &AppState,
    integration_id: &str,
) -> std::result::Result<Vec<ExternalIntegrationAuditItemView>, ApiError> {
    let mut items = Vec::new();
    let message_rows = sqlx::query(
        r#"
        select assistant_run_id,
               direction,
               platform,
               conversation_external_id,
               message_external_id,
               payload_summary,
               created_at
        from external_message_events
        where tenant_id = $1 and channel_connection_id = $2
        order by created_at desc
        limit 25
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in message_rows {
        let payload_summary = row.get::<Value, _>("payload_summary");
        items.push(ExternalIntegrationAuditItemView {
            item_type: "message".to_string(),
            created_at: row.get("created_at"),
            assistant_run_id: row
                .get::<Option<Uuid>, _>("assistant_run_id")
                .map(AssistantRunId),
            action_id: None,
            status: Some(row.get("direction")),
            failure_kind: None,
            summary: json!({
                "platform": row.get::<String, _>("platform"),
                "conversation_external_id": row.get::<String, _>("conversation_external_id"),
                "message_external_id": row.get::<String, _>("message_external_id"),
                "payload_summary": external_integration_redacted_summary(payload_summary),
            }),
        });
    }

    let search_rows = sqlx::query(
        r#"
        select run_id,
               payload,
               created_at
        from assistant_run_events
        where tenant_id = $1
          and event_name = 'assistant_run.external_search_evidence_required'
          and payload ->> 'channel_connection_id' = $2
        order by created_at desc
        limit 25
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in search_rows {
        let payload = row.get::<Value, _>("payload");
        items.push(ExternalIntegrationAuditItemView {
            item_type: "search_evidence".to_string(),
            created_at: row.get("created_at"),
            assistant_run_id: Some(AssistantRunId(row.get("run_id"))),
            action_id: None,
            status: Some("v3_search_evidence_required".to_string()),
            failure_kind: None,
            summary: json!({
                "action_type": "web_search",
                "freshness": payload
                    .get("freshness")
                    .and_then(Value::as_str)
                    .unwrap_or("unspecified"),
                "requires_v3_validation": payload
                    .get("requires_v3_validation")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
                "search_evidence_required": true,
                "no_live_search_claim": payload
                    .get("no_live_search_claim")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
                "query_chars": payload
                    .get("query_chars")
                    .and_then(Value::as_u64)
                    .unwrap_or(0),
                "message_external_id": payload
                    .get("message_external_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
                "source": "assistant_run.external_search_evidence_required",
            }),
        });
    }

    let action_rows = sqlx::query(
        r#"
        select id,
               assistant_run_id,
               action_type,
               target_system,
               arguments_redacted,
               confirmation_state,
               external_request_id,
               result_summary,
               failure_kind,
               updated_at
        from external_action_runs
        where tenant_id = $1
          and requester_summary ->> 'channel_connection_id' = $2
        order by updated_at desc
        limit 25
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in action_rows {
        let result_summary = row.get::<Value, _>("result_summary");
        let confirmation_state = row.get::<String, _>("confirmation_state");
        let status = result_summary
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or(confirmation_state.as_str())
            .to_string();
        items.push(ExternalIntegrationAuditItemView {
            item_type: "action".to_string(),
            created_at: row.get("updated_at"),
            assistant_run_id: row
                .get::<Option<Uuid>, _>("assistant_run_id")
                .map(AssistantRunId),
            action_id: Some(row.get("id")),
            status: Some(status),
            failure_kind: row.get("failure_kind"),
            summary: external_action_run_audit_summary(
                &row.get::<String, _>("action_type"),
                &row.get::<String, _>("target_system"),
                &row.get::<Value, _>("arguments_redacted"),
                &confirmation_state,
                row.get::<Option<String>, _>("external_request_id")
                    .as_deref(),
                &result_summary,
            ),
        });
    }

    Ok(items)
}

