async fn list_html_artifacts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<HtmlArtifactListQuery>,
) -> std::result::Result<Json<Vec<HtmlArtifactManifestView>>, ApiError> {
    let limit = normalize_html_artifact_list_limit(query.limit);
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let mut artifacts = Vec::<HtmlArtifactManifestView>::new();

    if let Some(plan_id) = query
        .report_plan_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let plan_id = parse_plan_id(plan_id)?;
        let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
        let (plan, report_artifacts) = load_report_render_summary_artifacts_for_plan(
            &state,
            plan_id,
            &active_secret_binding_ids,
            current_user_id,
            limit as usize,
        )
        .await?;
        persist_html_artifacts_for_report_plan(&state, &plan, &report_artifacts).await?;
        artifacts.extend(report_artifacts);
    } else if let Some(run_id) = query
        .assistant_run_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let run_id = parse_assistant_run_id(run_id)?;
        let run = load_visible_assistant_run_for_user(&state, run_id, current_user_id).await?;
        let stored_artifacts = state
            .storage
            .html_artifacts()
            .list_by_assistant_run(state.tenant_id, run.id, limit)
            .await
            .map_err(ApiError::from_storage)?;
        collect_html_artifacts_from_records(&stored_artifacts, &mut artifacts, limit as usize);
        let event_artifacts =
            load_html_artifacts_from_run_events(&state, run.id, limit as usize).await?;
        persist_html_artifacts_for_run(&state, &run, &event_artifacts).await?;
        artifacts.extend(event_artifacts);
        let draft_artifacts = load_static_page_handoff_artifacts_for_run(
            &state,
            run.id,
            current_user_id,
            limit as usize,
        )
        .await?;
        persist_html_artifacts_for_run(&state, &run, &draft_artifacts).await?;
        artifacts.extend(draft_artifacts);
        let quality_artifacts = load_static_page_data_quality_artifacts_for_run(
            &state,
            run.id,
            current_user_id,
            limit as usize,
        )
        .await?;
        persist_html_artifacts_for_run(&state, &run, &quality_artifacts).await?;
        artifacts.extend(quality_artifacts);
        let code_review_artifacts =
            load_code_review_summary_artifacts_for_run(&state, &run, limit as usize).await?;
        persist_html_artifacts_for_run(&state, &run, &code_review_artifacts).await?;
        artifacts.extend(code_review_artifacts);
    } else {
        let local_thread_id = required_field("local_thread_id", query.local_thread_id)?;
        validate_required("local_thread_id", &local_thread_id)?;
        let local_thread_id = local_thread_id.trim().to_string();
        let stored_artifacts = state
            .storage
            .html_artifacts()
            .list_by_local_thread(state.tenant_id, &local_thread_id, limit)
            .await
            .map_err(ApiError::from_storage)?;
        let visible_stored_artifacts = stored_artifacts
            .into_iter()
            .filter(|artifact| owner_user_id_is_visible(artifact.owner_user_id, current_user_id))
            .collect::<Vec<_>>();
        collect_html_artifacts_from_records(
            &visible_stored_artifacts,
            &mut artifacts,
            limit as usize,
        );
        let runs = state
            .storage
            .assistant_runs()
            .list_by_local_thread(state.tenant_id, &local_thread_id, limit)
            .await
            .map_err(ApiError::from_storage)?;
        for run in runs
            .into_iter()
            .filter(|run| owner_user_id_is_visible(run.user_id, current_user_id))
        {
            let event_artifacts =
                load_html_artifacts_from_run_events(&state, run.id, limit as usize).await?;
            persist_html_artifacts_for_run(&state, &run, &event_artifacts).await?;
            artifacts.extend(event_artifacts);
            let draft_artifacts = load_static_page_handoff_artifacts_for_run(
                &state,
                run.id,
                current_user_id,
                limit as usize,
            )
            .await?;
            persist_html_artifacts_for_run(&state, &run, &draft_artifacts).await?;
            artifacts.extend(draft_artifacts);
            let quality_artifacts = load_static_page_data_quality_artifacts_for_run(
                &state,
                run.id,
                current_user_id,
                limit as usize,
            )
            .await?;
            persist_html_artifacts_for_run(&state, &run, &quality_artifacts).await?;
            artifacts.extend(quality_artifacts);
            let code_review_artifacts =
                load_code_review_summary_artifacts_for_run(&state, &run, limit as usize).await?;
            persist_html_artifacts_for_run(&state, &run, &code_review_artifacts).await?;
            artifacts.extend(code_review_artifacts);
            if artifacts.len() >= limit as usize {
                break;
            }
        }
    }

    sort_and_dedupe_html_artifacts(&mut artifacts);
    artifacts.truncate(limit as usize);
    Ok(Json(artifacts))
}

async fn submit_html_artifact_event(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(artifact_id): Path<String>,
    Json(request): Json<SubmitHtmlArtifactEventRequest>,
) -> std::result::Result<(StatusCode, Json<SubmitHtmlArtifactEventResponse>), ApiError> {
    validate_required("artifact_id", &artifact_id)?;
    validate_required("event_type", &request.event_type)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let artifact_id = artifact_id.trim();
    let (run, artifact) =
        load_visible_html_artifact_for_submit(&state, current_user_id, artifact_id, &request)
            .await?;
    validate_html_artifact_event_request(&artifact, &request)?;
    let product_execution =
        apply_html_artifact_event_to_product(&state, current_user_id, &run, &artifact, &request)
            .await?;

    let mut event_payload = json!({
        "artifact_id": artifact.id.clone(),
        "artifact_title": artifact.title.clone(),
        "template_id": artifact.template_id.clone(),
        "source_type": artifact.source_type.clone(),
        "interaction_mode": artifact.interaction_mode.clone(),
        "payload": request.payload.clone(),
    });
    if let Some(execution) = product_execution {
        if let Some(object) = event_payload.as_object_mut() {
            object.insert("product_execution".to_string(), execution);
        }
    }

    let event = state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: request.event_type.trim().to_string(),
                payload: event_payload,
                created_at: Utc::now(),
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok((
        StatusCode::CREATED,
        Json(SubmitHtmlArtifactEventResponse {
            accepted: true,
            artifact,
            run: to_assistant_run_view(run),
            event: to_assistant_run_event_view(event),
        }),
    ))
}

async fn download_html_artifact_file(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((artifact_id, file_index)): Path<(String, usize)>,
    Query(query): Query<HtmlArtifactFileQuery>,
) -> std::result::Result<Response, ApiError> {
    validate_required("artifact_id", &artifact_id)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let request = SubmitHtmlArtifactEventRequest {
        assistant_run_id: query.assistant_run_id,
        local_thread_id: query.local_thread_id,
        event_type: String::new(),
        payload: Value::Null,
    };
    let (_run, artifact) = load_visible_html_artifact_for_submit(
        &state,
        current_user_id,
        artifact_id.trim(),
        &request,
    )
    .await?;
    let file = html_artifact_downloadable_file(&artifact, file_index)?;
    let bytes = fs::read(&file.path).map_err(|error| {
        ApiError::not_found(
            "html_artifact_file_unavailable",
            format!("generated artifact file is not available: {error}"),
        )
    })?;
    let mut builder = Response::builder()
        .status(StatusCode::OK)
        .header(header::CONTENT_TYPE, file.content_type)
        .header(header::CACHE_CONTROL, "no-store")
        .header(
            header::CONTENT_DISPOSITION,
            format!("attachment; filename=\"{}\"", file.file_name),
        );
    if let Ok(length) = HeaderValue::from_str(&bytes.len().to_string()) {
        builder = builder.header(header::CONTENT_LENGTH, length);
    }
    builder
        .body(axum::body::Body::from(bytes))
        .map_err(|error| {
            ApiError::internal(
                "html_artifact_download_response_failed",
                format!("failed to build artifact download response: {error}"),
            )
        })
}

async fn create_static_page_draft_for_assistant_run(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(run_id): Path<String>,
    Json(request): Json<CreateStaticPageDraftRequest>,
) -> std::result::Result<(StatusCode, Json<CreateStaticPageDraftResponse>), ApiError> {
    let run_id = parse_assistant_run_id(&run_id)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let run = load_visible_assistant_run_for_user(&state, run_id, current_user_id).await?;
    let owner_user_id = run.user_id.or(current_user_id);
    let prompt = request
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(run.user_prompt.trim());
    let title = request
        .title
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| derive_static_page_draft_title(prompt));
    let selected_scope = request
        .selected_scope
        .clone()
        .unwrap_or_else(|| run.selected_scope.clone());
    let visibility_snapshot = request
        .visibility_snapshot
        .clone()
        .unwrap_or_else(|| build_static_page_visibility_snapshot(&run, &selected_scope));
    let source_refs = if request.source_refs.is_null() {
        build_static_page_source_refs(&run)
    } else {
        request.source_refs.clone()
    };
    let draft_payload = if request.draft_payload.is_null() {
        build_initial_static_page_draft_payload(&run, prompt)
    } else {
        request.draft_payload.clone()
    };
    let status =
        status_from_static_page_payload(&draft_payload).unwrap_or(StaticPageDraftStatus::Draft);

    let draft = state
        .storage
        .static_page_drafts()
        .create(
            state.tenant_id,
            &NewStaticPageDraft {
                assistant_run_id: run.id,
                owner_user_id,
                title,
                status,
                selected_scope,
                visibility_snapshot,
                source_refs,
                draft_payload,
                created_at: Utc::now(),
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: "static_page_draft.created".to_string(),
                payload: json!({
                    "draft_id": draft.id,
                    "title": draft.title,
                    "status": draft.status.as_str(),
                }),
                created_at: draft.created_at,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok((
        StatusCode::CREATED,
        Json(CreateStaticPageDraftResponse {
            draft: to_static_page_draft_view(draft),
        }),
    ))
}

async fn list_static_page_drafts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<StaticPageDraftListQuery>,
) -> std::result::Result<Json<Vec<StaticPageDraftView>>, ApiError> {
    let limit = normalize_static_page_draft_list_limit(query.limit);
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let drafts = if let Some(run_id) = query
        .assistant_run_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let run_id = parse_assistant_run_id(run_id)?;
        state
            .storage
            .static_page_drafts()
            .list_by_assistant_run(state.tenant_id, run_id)
            .await
            .map_err(ApiError::from_storage)?
            .into_iter()
            .take(limit as usize)
            .collect()
    } else {
        let local_thread_id = required_field("local_thread_id", query.local_thread_id)?;
        validate_required("local_thread_id", &local_thread_id)?;
        state
            .storage
            .static_page_drafts()
            .list_by_local_thread(state.tenant_id, local_thread_id.trim(), limit)
            .await
            .map_err(ApiError::from_storage)?
    };

    Ok(Json(
        drafts
            .into_iter()
            .filter(|draft| static_page_owner_is_visible(draft.owner_user_id, current_user_id))
            .map(to_static_page_draft_view)
            .collect(),
    ))
}

