fn assistant_run_codex_shadow_comparison(
    output: &CodexConversationExecutorOutput,
    direct_react_enabled: bool,
    direct_runtime_manifest: &Value,
    direct_output_artifacts: &[Value],
    direct_react_events: &[AssistantRunReactEvent],
    selected_scope: &Value,
    current_artifact: Option<&Value>,
) -> Value {
    let artifact_types: Vec<Value> = direct_output_artifacts
        .iter()
        .filter_map(|artifact| artifact.get("type").and_then(Value::as_str))
        .map(|value| json!(value))
        .collect();
    let react_event_names: Vec<Value> = direct_react_events
        .iter()
        .map(|event| json!(event.event_name.as_str()))
        .collect();
    let direct_action_types =
        assistant_run_codex_direct_action_types(direct_output_artifacts, direct_react_events);
    let selected_intent = assistant_run_scope_intent(selected_scope);
    let static_page_context = selected_intent == "static_page"
        || current_artifact
            .map(assistant_run_is_static_page_artifact)
            .unwrap_or(false)
        || direct_output_artifacts.iter().any(|artifact| {
            artifact
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|kind| {
                    matches!(
                        kind,
                        "static_page_draft" | "static_page_image_job" | "static_page_render_output"
                    )
                })
        });
    let suggested_action_type = output
        .suggested_action
        .as_ref()
        .and_then(|action| {
            action
                .get("action_type")
                .or_else(|| action.get("actionType"))
                .or_else(|| action.get("type"))
        })
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    let suggested_action_allowed = suggested_action_type.as_ref().is_none_or(|action_type| {
        output
            .planned_action_types
            .iter()
            .any(|planned| planned == action_type)
    });
    let comparison_status = assistant_run_codex_shadow_comparison_status(
        &direct_action_types,
        suggested_action_type.as_deref(),
        suggested_action_allowed,
    );
    let direct_action_values: Vec<Value> = direct_action_types
        .iter()
        .map(|value| json!(value))
        .collect();

    json!({
        "mode": "shadow_comparison",
        "authoritative_executor": "direct",
        "codex_mutation_allowed": false,
        "codex_queue_allowed": false,
        "direct_state_authoritative": true,
        "static_page_flow_preserved": true,
        "static_page_context": static_page_context,
        "direct": {
            "react_enabled": direct_react_enabled,
            "runtime_mode": direct_runtime_manifest.get("mode").cloned().unwrap_or(Value::Null),
            "provider": direct_runtime_manifest.get("provider").cloned().unwrap_or(Value::Null),
            "model": direct_runtime_manifest.get("model").cloned().unwrap_or(Value::Null),
            "artifact_types": artifact_types,
            "react_event_names": react_event_names,
            "action_types": direct_action_values,
            "selected_intent": selected_intent,
        },
        "codex": {
            "transport": output.transport.as_str(),
            "status": output.status.as_str(),
            "codex_invoked": output.codex_invoked,
            "fallback_to_direct": output.fallback_to_direct,
            "planned_action_types": output.planned_action_types.clone(),
            "suggested_action_type": suggested_action_type,
            "suggested_action_allowed": suggested_action_allowed,
            "model_gateway": output.model_gateway.clone(),
        },
        "comparison": {
            "status": comparison_status,
            "codex_has_suggestion": output.suggested_action.is_some(),
            "actionable": false,
            "equivalence_scored": output.suggested_action.is_some(),
            "reason": if suggested_action_allowed {
                "shadow mode only; direct execution remains authoritative"
            } else {
                "codex suggested action is not in V3-provided action contracts"
            },
            "next_gate": "enable Codex mutation only after repeated matched shadow runs",
        }
    })
}

fn assistant_run_codex_direct_action_types(
    direct_output_artifacts: &[Value],
    direct_react_events: &[AssistantRunReactEvent],
) -> Vec<String> {
    let mut actions = Vec::new();
    for artifact in direct_output_artifacts {
        let Some(kind) = artifact.get("type").and_then(Value::as_str) else {
            continue;
        };
        let action = match kind {
            "static_page_draft" => Some("create_static_page_draft"),
            "static_page_image_job" => Some("submit_static_page_image_preview"),
            "static_page_render_output" => Some("render_static_page"),
            "assistant_message" => Some("final_answer"),
            "report_draft" => Some("create_report_draft"),
            _ => None,
        };
        if let Some(action) = action {
            push_unique_string(&mut actions, action);
        }
    }
    for event in direct_react_events {
        if let Some(action) = assistant_run_action_type_from_event_name(&event.event_name) {
            push_unique_string(&mut actions, action);
        }
    }
    actions
}

fn assistant_run_action_type_from_event_name(event_name: &str) -> Option<&'static str> {
    if event_name.contains("retrieve_evidence") {
        Some("retrieve_evidence")
    } else if event_name.contains("read_document_detail") {
        Some("read_document_detail")
    } else if event_name.contains("recall_conversation_memory") {
        Some("recall_conversation_memory")
    } else if event_name.contains("create_static_page_draft") {
        Some("create_static_page_draft")
    } else if event_name.contains("update_static_page_module") {
        Some("update_static_page_module")
    } else if event_name.contains("submit_static_page_image_preview") {
        Some("submit_static_page_image_preview")
    } else if event_name.contains("render_static_page") {
        Some("render_static_page")
    } else if event_name.contains("create_report_draft") {
        Some("create_report_draft")
    } else if event_name.contains("report_choice") {
        Some("report_choice")
    } else if event_name.contains("codex_host_task") {
        Some("codex_host_task")
    } else {
        None
    }
}

fn assistant_run_codex_shadow_comparison_status(
    direct_action_types: &[String],
    suggested_action_type: Option<&str>,
    suggested_action_allowed: bool,
) -> &'static str {
    let Some(suggested_action_type) = suggested_action_type else {
        return "no_codex_suggestion";
    };
    if !suggested_action_allowed {
        return "invalid_suggestion";
    }
    if direct_action_types
        .iter()
        .any(|action_type| action_type == suggested_action_type)
    {
        "matched"
    } else if direct_action_types.is_empty() {
        "codex_only"
    } else {
        "diverged"
    }
}

fn push_unique_string(items: &mut Vec<String>, item: &str) {
    if !items.iter().any(|existing| existing == item) {
        items.push(item.to_string());
    }
}

fn normalize_assistant_run_continue_max_steps(value: Option<usize>) -> usize {
    value
        .unwrap_or(ASSISTANT_RUN_CONTINUE_DEFAULT_MAX_STEPS)
        .clamp(1, ASSISTANT_RUN_CONTINUE_MAX_STEPS)
}

#[derive(Clone, Debug)]
struct ExternalAclFilterContext {
    principal: ExternalPrincipalContext,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct ExternalAclDocumentRef {
    source_id: String,
    document_external_id: String,
    revision_external_id: Option<String>,
}

async fn load_external_acl_filter_context(
    state: &AppState,
    selected_scope: &Value,
) -> std::result::Result<Option<ExternalAclFilterContext>, ApiError> {
    if selected_scope.get("type").and_then(Value::as_str) != Some("external_channel") {
        return Ok(None);
    }
    let platform = required_scope_string(selected_scope, "platform")?;
    let external_user_id = selected_scope
        .get("sender_external_id")
        .or_else(|| selected_scope.get("sender_external_user_id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            ApiError::bad_request(
                "external_principal_missing",
                "external channel scope requires sender_external_id before retrieval".to_string(),
            )
        })?;

    let row = sqlx::query(
        r#"
        select v3_user_id,
               trust_level,
               is_disabled,
               external_department_ids,
               external_group_ids,
               external_role_ids
        from external_principals
        where tenant_id = $1 and platform = $2 and external_user_id = $3
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(platform)
    .bind(external_user_id)
    .fetch_optional(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let principal = if let Some(row) = row {
        ExternalPrincipalContext {
            tenant_id: state.tenant_id,
            platform: platform.to_string(),
            external_user_id: external_user_id.to_string(),
            external_department_ids: json_string_array(row.get("external_department_ids")),
            external_group_ids: json_string_array(row.get("external_group_ids")),
            external_role_ids: json_string_array(row.get("external_role_ids")),
            v3_user_id: row.get::<Option<Uuid>, _>("v3_user_id").map(UserId),
            trust_level: ExternalPrincipalTrustLevel::from_str(
                row.get::<String, _>("trust_level").as_str(),
            ),
            is_disabled: row.get("is_disabled"),
        }
    } else {
        ExternalPrincipalContext {
            tenant_id: state.tenant_id,
            platform: platform.to_string(),
            external_user_id: external_user_id.to_string(),
            external_department_ids: Vec::new(),
            external_group_ids: Vec::new(),
            external_role_ids: Vec::new(),
            v3_user_id: None,
            trust_level: ExternalPrincipalTrustLevel::Unresolved,
            is_disabled: false,
        }
    };

    Ok(Some(ExternalAclFilterContext { principal }))
}

fn required_scope_string<'a>(
    selected_scope: &'a Value,
    field_name: &str,
) -> std::result::Result<&'a str, ApiError> {
    selected_scope
        .get(field_name)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            ApiError::bad_request(
                "external_scope_invalid",
                format!("external channel scope requires {field_name}"),
            )
        })
}

async fn filter_retrieval_evidences_for_external_acl(
    state: &AppState,
    context: Option<&ExternalAclFilterContext>,
    evidences: Vec<RetrievalEvidence>,
) -> std::result::Result<Vec<RetrievalEvidence>, ApiError> {
    let Some(context) = context else {
        return Ok(evidences);
    };
    let resolver = ScopeResolver;
    let mut visible = Vec::new();
    let mut acl_cache =
        HashMap::<ExternalAclDocumentRef, Option<ExternalDocumentAclSnapshot>>::new();

    for evidence in evidences {
        let Some(acl_ref) = external_acl_document_ref_from_value(&evidence.evidence_manifest)
        else {
            continue;
        };
        let acl = load_external_acl_snapshot_cached(state, &mut acl_cache, &acl_ref).await?;
        if acl
            .as_ref()
            .map(|snapshot| {
                resolver
                    .can_access_external_document(&context.principal, snapshot)
                    .allowed
            })
            .unwrap_or(false)
        {
            visible.push(evidence);
        }
    }

    Ok(visible)
}

async fn document_is_visible_for_external_acl(
    state: &AppState,
    context: Option<&ExternalAclFilterContext>,
    document: &Document,
) -> std::result::Result<bool, ApiError> {
    let Some(context) = context else {
        return Ok(true);
    };
    let metadata = Value::Object(Map::from_iter(document.metadata.clone()));
    let Some(acl_ref) = external_acl_document_ref_from_value(&metadata) else {
        return Ok(false);
    };
    let mut acl_cache =
        HashMap::<ExternalAclDocumentRef, Option<ExternalDocumentAclSnapshot>>::new();
    let Some(acl) = load_external_acl_snapshot_cached(state, &mut acl_cache, &acl_ref).await?
    else {
        return Ok(false);
    };
    Ok(ScopeResolver
        .can_access_external_document(&context.principal, &acl)
        .allowed)
}

async fn load_external_acl_snapshot_cached(
    state: &AppState,
    cache: &mut HashMap<ExternalAclDocumentRef, Option<ExternalDocumentAclSnapshot>>,
    acl_ref: &ExternalAclDocumentRef,
) -> std::result::Result<Option<ExternalDocumentAclSnapshot>, ApiError> {
    if let Some(snapshot) = cache.get(acl_ref) {
        return Ok(snapshot.clone());
    }
    let snapshot = load_external_acl_snapshot(state, acl_ref).await?;
    cache.insert(acl_ref.clone(), snapshot.clone());
    Ok(snapshot)
}

async fn load_external_acl_snapshot(
    state: &AppState,
    acl_ref: &ExternalAclDocumentRef,
) -> std::result::Result<Option<ExternalDocumentAclSnapshot>, ApiError> {
    let revision_filter = acl_ref.revision_external_id.as_deref().unwrap_or("");
    let row = sqlx::query(
        r#"
        select revision_external_id, acl_snapshot, acl_hash
        from external_permission_snapshots
        where tenant_id = $1
          and source_id = $2
          and document_external_id = $3
          and ($4 = '' or coalesce(revision_external_id, '') = $4)
        order by captured_at desc
        limit 1
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(&acl_ref.source_id)
    .bind(&acl_ref.document_external_id)
    .bind(revision_filter)
    .fetch_optional(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let Some(row) = row else {
        return Ok(None);
    };
    let acl_snapshot: Value = row.get("acl_snapshot");
    Ok(Some(ExternalDocumentAclSnapshot {
        source_id: acl_ref.source_id.clone(),
        document_external_id: acl_ref.document_external_id.clone(),
        revision_external_id: row
            .get::<Option<String>, _>("revision_external_id")
            .or_else(|| acl_ref.revision_external_id.clone()),
        allowed_user_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_user_external_ids",
            "user",
        ),
        allowed_department_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_department_external_ids",
            "department",
        ),
        allowed_group_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_group_external_ids",
            "group",
        ),
        allowed_role_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_role_external_ids",
            "role",
        ),
        denied_user_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_user_external_ids",
            "user",
        ),
        denied_department_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_department_external_ids",
            "department",
        ),
        denied_group_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_group_external_ids",
            "group",
        ),
        denied_role_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_role_external_ids",
            "role",
        ),
        acl_hash: row.get("acl_hash"),
    }))
}

fn external_acl_document_ref_from_value(value: &Value) -> Option<ExternalAclDocumentRef> {
    external_acl_document_ref_from_object(value).or_else(|| {
        let object = value.as_object()?;
        for key in [
            "external_acl",
            "externalAcl",
            "source_acl_snapshot",
            "sourceAclSnapshot",
            "external_source",
            "externalSource",
            "evidence",
        ] {
            if let Some(found) = object
                .get(key)
                .and_then(external_acl_document_ref_from_value)
            {
                return Some(found);
            }
        }
        None
    })
}

fn external_acl_document_ref_from_object(value: &Value) -> Option<ExternalAclDocumentRef> {
    let object = value.as_object()?;
    let source_id = object_string(object, &["source_id", "sourceId"])?;
    let document_external_id = object_string(
        object,
        &[
            "document_external_id",
            "documentExternalId",
            "external_document_id",
        ],
    )?;
    let revision_external_id = object_string(
        object,
        &["revision_external_id", "revisionExternalId", "revision"],
    );
    Some(ExternalAclDocumentRef {
        source_id,
        document_external_id,
        revision_external_id,
    })
}

fn object_string(object: &Map<String, Value>, keys: &[&str]) -> Option<String> {
    keys.iter()
        .filter_map(|key| object.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .next()
}

fn acl_subject_ids(snapshot: &Value, flat_key: &str, subject_type: &str) -> Vec<String> {
    let mut ids = json_string_array(snapshot.get(flat_key).cloned().unwrap_or(Value::Null));
    ids.extend(acl_nested_subject_ids(snapshot, "allow", subject_type));
    dedupe_strings(ids)
}

fn acl_denied_subject_ids(snapshot: &Value, flat_key: &str, subject_type: &str) -> Vec<String> {
    let mut ids = json_string_array(snapshot.get(flat_key).cloned().unwrap_or(Value::Null));
    ids.extend(acl_nested_subject_ids(snapshot, "deny", subject_type));
    dedupe_strings(ids)
}

fn acl_nested_subject_ids(
    snapshot: &Value,
    collection_key: &str,
    subject_type: &str,
) -> Vec<String> {
    snapshot
        .get(collection_key)
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|item| {
            item.get("subject_type")
                .or_else(|| item.get("subjectType"))
                .and_then(Value::as_str)
                == Some(subject_type)
        })
        .filter_map(|item| {
            item.get("subject_external_id")
                .or_else(|| item.get("subjectExternalId"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        })
        .collect()
}

fn json_string_array(value: Value) -> Vec<String> {
    value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn dedupe_strings(values: Vec<String>) -> Vec<String> {
    let mut deduped = Vec::new();
    for value in values {
        if !deduped.contains(&value) {
            deduped.push(value);
        }
    }
    deduped
}

fn external_acl_supply_filter_summary(context: Option<&ExternalAclFilterContext>) -> Value {
    context
        .map(|context| {
            json!({
                "status": "enabled",
                "platform": context.principal.platform,
                "external_user_id": context.principal.external_user_id,
                "trust_level": external_principal_trust_level_label(&context.principal.trust_level),
                "permission_boundary": "source_acl_snapshot_before_model_context",
            })
        })
        .unwrap_or(Value::Null)
}

fn external_principal_trust_level_label(level: &ExternalPrincipalTrustLevel) -> &'static str {
    match level {
        ExternalPrincipalTrustLevel::Unresolved => "unresolved",
        ExternalPrincipalTrustLevel::Guest => "guest",
        ExternalPrincipalTrustLevel::ExternalUser => "external_user",
        ExternalPrincipalTrustLevel::Employee => "employee",
        ExternalPrincipalTrustLevel::Manager => "manager",
        ExternalPrincipalTrustLevel::Admin => "admin",
        ExternalPrincipalTrustLevel::SystemOperator => "system_operator",
    }
}

async fn build_assistant_run_evidence_state(
    state: &AppState,
    selected_scope: &Value,
    prompt: &str,
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<Value, ApiError> {
    let dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    let conversation_memory_requested = selected_scope_requests_conversation_memory(selected_scope);
    if dataset_ids.is_empty() && !conversation_memory_requested {
        let empty_items: Vec<Value> = Vec::new();
        return Ok(json!({
            "status": "not_requested",
            "policy": "host_supplies_model_answers",
            "intent": assistant_run_scope_intent(selected_scope),
            "supply_policy": assistant_run_scope_supply_policy(selected_scope),
            "action_policy": assistant_run_scope_action_policy(selected_scope),
            "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
            "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
            "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
            "supply_quality": assistant_run_supply_quality_report(
                selected_scope,
                false,
                &empty_items,
                &empty_items,
                &empty_items,
                &empty_items,
                0,
                0,
            ),
            "supplied_items": [],
        }));
    }

    let prefer_detail = assistant_run_scope_prefers_detail(selected_scope);
    let limit = assistant_run_evidence_limit_for_scope(selected_scope);
    let external_acl_filter = load_external_acl_filter_context(state, selected_scope).await?;
    let mut supplied_items = Vec::new();
    let mut supplied_datasets = Vec::new();
    let mut supplied_memory_items = Vec::new();
    let mut media_context_by_document: HashMap<DocumentId, Option<Value>> = HashMap::new();

    for dataset_id in dataset_ids
        .into_iter()
        .take(ASSISTANT_RUN_EVIDENCE_DATASET_LIMIT)
    {
        let dataset = load_visible_dataset_for_user(
            state,
            dataset_id,
            active_secret_binding_ids,
            current_user_id,
        )
        .await?;
        supplied_datasets.push(json!({
            "id": dataset.id,
            "key": dataset.key.clone(),
            "title": dataset.title.clone(),
            "visibility": dataset.visibility.as_str(),
        }));

        let evidences = state
            .storage
            .retrieval_evidences()
            .list_latest_by_dataset(
                state.tenant_id,
                dataset.id,
                retrieval_search_scan_limit(limit),
            )
            .await
            .map_err(ApiError::from_storage)?;
        let evidences = filter_retrieval_evidences_for_visible_documents(
            state,
            dataset.id,
            evidences,
            current_user_id,
        )
        .await?;
        let evidences = filter_retrieval_evidences_for_external_acl(
            state,
            external_acl_filter.as_ref(),
            evidences,
        )
        .await?;

        let ranked_evidences = rank_retrieval_evidences_for_prompt(&evidences, prompt, limit);
        if ranked_evidences.is_empty() {
            let fallback_items = build_assistant_run_chunk_fallback_supply(
                state,
                &dataset,
                prompt,
                limit,
                current_user_id,
                external_acl_filter.as_ref(),
                &mut media_context_by_document,
            )
            .await?;
            supplied_items.extend(fallback_items);
            continue;
        }

        for ranked in ranked_evidences {
            let media_context = assistant_run_media_context_for_document(
                state,
                ranked.evidence.document_id,
                &mut media_context_by_document,
            )
            .await?;
            let mut supplied_item = json!({
                "type": "retrieval_evidence",
                "dataset_id": ranked.evidence.dataset_id,
                "document_id": ranked.evidence.document_id,
                "document_chunk_id": ranked.evidence.document_chunk_id,
                "retrieval_evidence_id": ranked.evidence.id,
                "chunk_index": ranked.evidence.chunk_index,
                "source_locator": ranked.evidence.source_locator.clone(),
                "summary": ranked.evidence.summary.clone(),
                "content_excerpt": ranked.evidence.content_excerpt.clone(),
                "payload_filter_key": ranked.evidence.payload_filter_key.clone(),
                "score": ranked.score,
                "lexical_score": ranked.lexical_score,
                "recall_score": ranked.recall_score,
                "evidence_manifest": ranked.evidence.evidence_manifest.clone(),
            });
            if let Some(media_context) = media_context {
                if let Some(object) = supplied_item.as_object_mut() {
                    object.insert("media_context".to_string(), media_context);
                }
            }
            supplied_items.push(supplied_item);
        }
    }

    if conversation_memory_requested {
        if let Some(local_thread_id) = local_thread_id
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            let items = state
                .storage
                .conversation_memory_items()
                .list_by_local_thread(
                    state.tenant_id,
                    local_thread_id,
                    None,
                    assistant_run_conversation_memory_limit(),
                )
                .await
                .map_err(ApiError::from_storage)?;

            for item in items
                .into_iter()
                .filter(|item| owner_user_id_is_visible(item.user_id, current_user_id))
                .filter(assistant_run_memory_item_is_supply_eligible)
            {
                let supplied_item = json!({
                    "type": "conversation_memory_item",
                    "conversation_memory_item_id": item.id,
                    "local_thread_id": item.local_thread_id,
                    "role": item.role.as_str(),
                    "item_kind": item.item_kind,
                    "summary": item.summary,
                    "source_message_refs": item.source_message_refs,
                    "artifact_refs": item.artifact_refs,
                    "metadata": item.metadata,
                    "created_at": item.created_at,
                    "updated_at": item.updated_at,
                });
                supplied_memory_items.push(supplied_item.clone());
                supplied_items.push(supplied_item);
            }
        }
    }

    let status = if supplied_items.is_empty() {
        "empty"
    } else {
        "supplied"
    };
    let detail_targets = assistant_run_detail_targets_for_scope(selected_scope, &supplied_items);
    let fallback_supply_count = assistant_run_fallback_supply_count(&supplied_items);
    let supply_quality = assistant_run_supply_quality_report(
        selected_scope,
        true,
        &supplied_items,
        &supplied_datasets,
        &supplied_memory_items,
        &detail_targets,
        fallback_supply_count,
        limit,
    );
    Ok(json!({
        "status": status,
        "policy": "host_supplies_model_answers",
        "intent": assistant_run_scope_intent(selected_scope),
        "supply_policy": assistant_run_scope_supply_policy(selected_scope),
        "action_policy": assistant_run_scope_action_policy(selected_scope),
        "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
        "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
        "detail_preferred": prefer_detail,
        "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
        "recommended_actions": assistant_run_recommended_supply_actions(selected_scope, !supplied_items.is_empty()),
        "supply_quality": supply_quality,
        "detail_targets": detail_targets,
        "selected_scope": selected_scope,
        "datasets": supplied_datasets,
        "conversation_memory_items": supplied_memory_items,
        "supplied_items": supplied_items,
        "external_acl_filter": external_acl_supply_filter_summary(external_acl_filter.as_ref()),
        "fallback_supply_count": fallback_supply_count,
        "fallback_supply_policy": if fallback_supply_count > 0 { "visible_document_chunks_when_retrieval_evidence_missing" } else { "not_used" },
        "limit": limit,
    }))
}

async fn build_assistant_run_chunk_fallback_supply(
    state: &AppState,
    dataset: &Dataset,
    prompt: &str,
    limit: usize,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    media_context_by_document: &mut HashMap<DocumentId, Option<Value>>,
) -> std::result::Result<Vec<Value>, ApiError> {
    if limit == 0 {
        return Ok(Vec::new());
    }

    let documents = state
        .storage
        .documents()
        .list_by_dataset(state.tenant_id, dataset.id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
        .collect::<Vec<_>>();
    let mut sources = Vec::new();
    for document in documents {
        if !document_is_visible_for_external_acl(state, external_acl_filter, &document).await? {
            continue;
        }
        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        for chunk in chunks
            .into_iter()
            .filter(|chunk| !chunk.content.trim().is_empty())
        {
            sources.push((document.clone(), chunk));
        }
    }

    let ranked = rank_document_chunks_for_prompt(sources, prompt, limit);
    let mut items = Vec::with_capacity(ranked.len());
    for ranked in ranked {
        let media_context = assistant_run_media_context_for_document(
            state,
            ranked.chunk.document_id,
            media_context_by_document,
        )
        .await?;
        let mut supplied_item = json!({
            "type": "retrieval_evidence",
            "source": "document_chunk_fallback",
            "fallback_reason": "retrieval_evidence_unavailable",
            "dataset_id": ranked.chunk.dataset_id,
            "document_id": ranked.chunk.document_id,
            "document_chunk_id": ranked.chunk.id,
            "chunk_index": ranked.chunk.chunk_index,
            "source_locator": document_chunk_fallback_source_locator(&ranked.document, &ranked.chunk),
            "summary": document_chunk_fallback_summary(&ranked.document, &ranked.chunk),
            "content_excerpt": truncate_assistant_supply_text(&ranked.chunk.content, 900),
            "payload_filter_key": format!("dataset/{}/document/{}", dataset.key, ranked.document.object_key),
            "score": ranked.score,
            "lexical_score": ranked.lexical_score,
            "recall_score": 0.0,
            "evidence_manifest": {
                "fallback": {
                    "source": "document_chunk",
                    "reason": "retrieval_evidence_unavailable"
                },
                "embedding": {
                    "term_weights": limited_lexical_term_weights(&ranked.search_text, 40)
                }
            },
        });
        if let Some(media_context) = media_context {
            if let Some(object) = supplied_item.as_object_mut() {
                object.insert("media_context".to_string(), media_context);
            }
        }
        items.push(supplied_item);
    }
    Ok(items)
}

fn assistant_run_supply_quality_report(
    selected_scope: &Value,
    supply_requested: bool,
    supplied_items: &[Value],
    supplied_datasets: &[Value],
    supplied_memory_items: &[Value],
    detail_targets: &[Value],
    fallback_supply_count: usize,
    limit: usize,
) -> Value {
    let supplied_item_count = supplied_items.len();
    let indexed_evidence_count = supplied_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str) == Some("retrieval_evidence")
                && item
                    .get("source")
                    .and_then(Value::as_str)
                    .map(|source| source != "document_chunk_fallback")
                    .unwrap_or(true)
        })
        .count();
    let media_context_count = supplied_items
        .iter()
        .filter(|item| item.get("media_context").is_some())
        .count();
    let citation_locators = assistant_run_supply_citation_locators(supplied_items, 8);
    let prefer_detail = assistant_run_scope_prefers_detail(selected_scope);
    let status = if !supply_requested {
        "not_requested"
    } else if supplied_item_count == 0 {
        "missing"
    } else if fallback_supply_count > 0 || (prefer_detail && !detail_targets.is_empty()) {
        "partial"
    } else {
        "grounded"
    };
    let mut notes = Vec::new();
    if !supply_requested {
        notes.push("ordinary_chat_without_forced_supply");
    }
    if indexed_evidence_count > 0 {
        notes.push("indexed_retrieval_evidence_available");
    }
    if fallback_supply_count > 0 {
        notes.push("fallback_visible_document_chunks_used");
    }
    if !detail_targets.is_empty() {
        notes.push("detail_read_recommended_before_high_confidence_claims");
    }
    if media_context_count > 0 {
        notes.push("media_context_available_with_timestamps_when_present");
    }
    if !supplied_memory_items.is_empty() {
        notes.push("conversation_memory_supplied_by_intent");
    }
    if citation_locators.is_empty() && supply_requested {
        notes.push("no_source_locator_available");
    }

    json!({
        "status": status,
        "intent": assistant_run_scope_intent(selected_scope),
        "supplyRequested": supply_requested,
        "qualityFirst": assistant_run_scope_prefers_detail(selected_scope)
            || selected_scope_requests_conversation_memory(selected_scope),
        "selectedDatasetCount": supplied_datasets.len(),
        "suppliedItemCount": supplied_item_count,
        "indexedEvidenceCount": indexed_evidence_count,
        "fallbackChunkCount": fallback_supply_count,
        "conversationMemoryItemCount": supplied_memory_items.len(),
        "mediaContextCount": media_context_count,
        "detailTargetCount": detail_targets.len(),
        "limit": limit,
        "citationLocatorCount": citation_locators.len(),
        "citationLocators": citation_locators,
        "notes": notes,
        "modelGuidance": [
            "treat supplied_items as citable context, not an answer template",
            "distinguish supplied document facts from general model knowledge",
            "read detail_targets before asserting exact source wording, tables, OCR, or media timestamps"
        ],
    })
}

fn assistant_run_supply_citation_locators(items: &[Value], limit: usize) -> Vec<String> {
    let mut locators = Vec::new();
    let mut seen = BTreeSet::new();
    for item in items {
        let Some(locator) = item
            .get("source_locator")
            .or_else(|| item.get("sourceLocator"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        if seen.insert(locator.to_string()) {
            locators.push(locator.to_string());
        }
        if locators.len() >= limit {
            break;
        }
    }
    locators
}

fn assistant_run_evidence_limit_for_scope(selected_scope: &Value) -> usize {
    if assistant_run_scope_prefers_detail(selected_scope)
        && !selected_dataset_ids_from_scope(selected_scope).is_empty()
    {
        ASSISTANT_RUN_EVIDENCE_MAX_LIMIT
    } else {
        assistant_run_evidence_limit()
    }
}

fn assistant_run_evidence_limit() -> usize {
    std::env::var("ASSISTANT_RUN_EVIDENCE_LIMIT")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(ASSISTANT_RUN_EVIDENCE_DEFAULT_LIMIT)
        .clamp(1, ASSISTANT_RUN_EVIDENCE_MAX_LIMIT)
}

fn assistant_run_recommended_supply_actions(
    selected_scope: &Value,
    has_supplied_items: bool,
) -> Vec<&'static str> {
    let mut actions = Vec::new();
    let recommended_tool_actions = assistant_run_scope_recommended_tool_actions(selected_scope);
    if !selected_dataset_ids_from_scope(selected_scope).is_empty() {
        actions.push("retrieve_evidence");
        if assistant_run_scope_prefers_detail(selected_scope) && has_supplied_items {
            actions.push("read_document_detail");
        }
    }
    if selected_scope_requests_conversation_memory(selected_scope) {
        actions.push("recall_conversation_memory");
    }
    match assistant_run_scope_intent(selected_scope) {
        "static_page" => actions.push("create_static_page_draft"),
        "report" => actions.push("list_report_options"),
        _ => {}
    }
    if recommended_tool_actions
        .iter()
        .any(|action| action == "media.resolve_video_url")
    {
        actions.push("resolve_video_url");
    }
    if recommended_tool_actions
        .iter()
        .any(|action| action == "media.extract_ppt_transcript")
    {
        actions.push("extract_video_ppt_transcript");
    }
    actions
}

fn assistant_run_fallback_supply_count(supplied_items: &[Value]) -> usize {
    supplied_items
        .iter()
        .filter(|item| {
            item.get("source")
                .and_then(Value::as_str)
                .is_some_and(|source| source == "document_chunk_fallback")
        })
        .count()
}

fn document_chunk_fallback_source_locator(document: &Document, chunk: &DocumentChunk) -> String {
    let base = if document.object_key.trim().is_empty() {
        document.title.trim()
    } else {
        document.object_key.trim()
    };
    format!("{}#chunk={}", base, chunk.chunk_index)
}

fn document_chunk_fallback_summary(document: &Document, chunk: &DocumentChunk) -> String {
    let title = if document.title.trim().is_empty() {
        document.object_key.trim()
    } else {
        document.title.trim()
    };
    let excerpt = truncate_assistant_supply_text(&chunk.content, 180);
    if excerpt.is_empty() {
        format!("{title} chunk {}", chunk.chunk_index)
    } else {
        format!("{title} chunk {}: {excerpt}", chunk.chunk_index)
    }
}

fn truncate_assistant_supply_text(value: &str, max_chars: usize) -> String {
    value
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .take(max_chars)
        .collect()
}

fn assistant_run_detail_targets_for_scope(
    selected_scope: &Value,
    supplied_items: &[Value],
) -> Vec<Value> {
    if !assistant_run_scope_prefers_detail(selected_scope) {
        return Vec::new();
    }

    let mut seen_documents = HashSet::new();
    supplied_items
        .iter()
        .filter(|item| {
            item.get("type")
                .and_then(Value::as_str)
                .is_some_and(|item_type| item_type == "retrieval_evidence")
        })
        .filter_map(|item| {
            let document_id = item.get("document_id").or_else(|| item.get("documentId"))?;
            let document_key = document_id
                .as_str()
                .map(ToString::to_string)
                .unwrap_or_else(|| document_id.to_string());
            if document_key.trim().is_empty() || !seen_documents.insert(document_key) {
                return None;
            }

            let media_context = item
                .get("media_context")
                .or_else(|| item.get("mediaContext"));
            let has_media_context = media_context.is_some_and(Value::is_object);
            let has_timestamped_evidence = media_context
                .and_then(|context| context.get("has_timestamped_evidence"))
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let reason = if has_timestamped_evidence {
                "timestamped_media_detail_available"
            } else if has_media_context {
                "media_detail_available"
            } else {
                "detail_first_scope"
            };

            let mut target = Map::new();
            target.insert("type".to_string(), json!("document_detail_target"));
            for key in [
                "dataset_id",
                "datasetId",
                "document_id",
                "documentId",
                "retrieval_evidence_id",
                "retrievalEvidenceId",
                "chunk_index",
                "chunkIndex",
                "source_locator",
                "sourceLocator",
            ] {
                if let Some(value) = item.get(key).filter(|value| !value.is_null()) {
                    target.insert(key.to_string(), value.clone());
                }
            }
            target.insert("reason".to_string(), json!(reason));
            target.insert("has_media_context".to_string(), json!(has_media_context));
            target.insert(
                "has_timestamped_evidence".to_string(),
                json!(has_timestamped_evidence),
            );
            Some(Value::Object(target))
        })
        .take(ASSISTANT_RUN_DETAIL_TARGET_LIMIT)
        .collect()
}

async fn assistant_run_media_context_for_document(
    state: &AppState,
    document_id: DocumentId,
    cache: &mut HashMap<DocumentId, Option<Value>>,
) -> std::result::Result<Option<Value>, ApiError> {
    if let Some(cached) = cache.get(&document_id) {
        return Ok(cached.clone());
    }

    let chunks = state
        .storage
        .document_chunks()
        .list_by_document(state.tenant_id, document_id)
        .await
        .map_err(ApiError::from_storage)?;
    let context = extract_media_metadata_from_chunks(&chunks)
        .as_ref()
        .and_then(build_assistant_run_media_supply_context);
    cache.insert(document_id, context.clone());
    Ok(context)
}

fn build_assistant_run_media_supply_context(raw_media_metadata: &Value) -> Option<Value> {
    let media_kind = raw_media_metadata
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let parse_status = raw_media_metadata
        .get("parse_status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let transcript_windows = collect_media_transcript_segments(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let scene_windows = collect_media_scenes(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let keyframe_ocr_snippets = collect_media_ocr_snippets(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let provider_evidence = collect_media_provider_evidence(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let has_timestamped_evidence = !transcript_windows.is_empty()
        || !scene_windows.is_empty()
        || !keyframe_ocr_snippets.is_empty();
    let has_context = has_timestamped_evidence
        || !provider_evidence.is_empty()
        || !matches!(media_kind, "unknown" | "");
    if !has_context {
        return None;
    }

    Some(json!({
        "media_kind": media_kind,
        "parse_status": parse_status,
        "has_timestamped_evidence": has_timestamped_evidence,
        "transcript_windows": transcript_windows,
        "scene_windows": scene_windows,
        "keyframe_ocr_snippets": keyframe_ocr_snippets,
        "provider_evidence": provider_evidence,
    }))
}

fn assistant_run_artifact_scope_candidates(
    client_candidates: &[Value],
    current_artifact: Option<&Value>,
) -> Vec<Value> {
    let Some(current_artifact) = current_artifact else {
        return Vec::new();
    };
    let Some(artifact_id) = static_page_artifact_id(current_artifact) else {
        return Vec::new();
    };
    let client_static_page_candidate = client_candidates.iter().find(|candidate| {
        candidate.get("type").and_then(Value::as_str) == Some("static_page_draft")
            && candidate.get("id").and_then(Value::as_str) == Some(artifact_id.as_str())
    });
    let label = static_page_artifact_label(current_artifact)
        .or_else(|| {
            client_static_page_candidate
                .and_then(|candidate| candidate.get("label"))
                .and_then(Value::as_str)
                .map(truncate_scope_candidate_text)
        })
        .unwrap_or_else(|| "当前静态页草稿".to_string());

    vec![json!({
        "type": "static_page_draft",
        "id": artifact_id,
        "label": label,
        "status": static_page_artifact_string(current_artifact, &["status", "backendStatus", "backend_status"]).unwrap_or_default(),
        "styleDirection": static_page_artifact_string(current_artifact, &["styleDirection", "style_direction"]).unwrap_or_default(),
        "moduleCount": static_page_artifact_module_count(current_artifact),
        "previewStatus": static_page_artifact_preview_status(current_artifact).unwrap_or_default(),
        "finalRenderStatus": static_page_artifact_final_status(current_artifact).unwrap_or_default(),
        "previewStale": static_page_artifact_preview_stale(current_artifact),
        "confidence": "high",
        "reason": "当前主区域打开了静态页草稿",
        "source": "active_artifact",
    })]
}

fn assistant_run_scope_with_current_artifact_context(
    selected_scope: Value,
    current_artifact: Option<&Value>,
    prompt: &str,
) -> Value {
    let Some(current_artifact) = current_artifact else {
        return selected_scope;
    };
    if !assistant_run_is_static_page_artifact(current_artifact) {
        return selected_scope;
    }
    let current_intent = assistant_run_scope_intent(&selected_scope);
    if current_intent != "static_page" && !prompt_touches_current_static_page_artifact(prompt) {
        return selected_scope;
    }

    let mut selected_scope = selected_scope;
    ensure_json_object(&mut selected_scope);
    let has_dataset = !selected_dataset_ids_from_scope(&selected_scope).is_empty();
    let has_memory = selected_scope_requests_conversation_memory(&selected_scope);
    if let Some(object) = selected_scope.as_object_mut() {
        object.insert("intent".to_string(), json!("static_page"));
        object.insert(
            "supply_policy".to_string(),
            assistant_run_active_static_page_supply_policy(has_dataset, has_memory),
        );
    }
    selected_scope
}

fn assistant_run_active_static_page_supply_policy(has_dataset: bool, has_memory: bool) -> Value {
    let mut recommended_actions = Vec::new();
    if has_dataset {
        recommended_actions.push("retrieval.search");
        recommended_actions.push("retrieval.read_detail");
    }
    recommended_actions.push("static_page.update_draft");

    json!({
        "intent": "static_page",
        "answerPolicy": "model_authored_host_supplied",
        "currentArtifactPolicy": "active_static_page_draft",
        "actionPolicy": "model_may_request_controlled_actions_host_validates",
        "contextBudgetPolicy": if has_dataset || has_memory {
            "quality_first_token_tolerant"
        } else {
            "compact_until_retrieval_needed"
        },
        "candidatePolicy": if has_dataset {
            "selected_or_inferred_visible_datasets_only"
        } else {
            "ordinary_chat_without_forced_dataset"
        },
        "historyPolicy": if has_memory {
            "intent_gated_selected"
        } else {
            "intent_gated"
        },
        "retrievalPolicy": if has_dataset {
            "detail_first"
        } else {
            "not_requested"
        },
        "preferDetail": has_dataset,
        "recommendedActions": recommended_actions,
        "noFakeData": true,
    })
}

fn prompt_touches_current_static_page_artifact(prompt: &str) -> bool {
    let prompt = prompt.trim();
    if prompt.is_empty() {
        return false;
    }
    let lower_prompt = prompt.to_ascii_lowercase();
    [
        "静态页",
        "静态页面",
        "页面规划",
        "一页",
        "生成页面",
        "落地页",
        "模块",
        "效果图",
        "出图",
        "标题",
        "文案",
        "内容",
        "数据",
        "图表",
        "布局",
        "调整",
        "修改",
        "改",
        "换",
        "确认",
        "导出",
        "继续",
        "接着",
        "下一步",
        "刚才",
        "上面",
        "之前",
        "这个",
        "那版",
        "草稿",
        "柱状图",
        "折线图",
        "环图",
        "看板",
    ]
    .iter()
    .any(|hint| prompt.contains(hint))
        || ["dashboard", "chart", "kpi", "export"]
            .iter()
            .any(|hint| lower_prompt.contains(hint))
}

fn assistant_run_current_artifact_brief(current_artifact: &Value) -> Value {
    if assistant_run_is_static_page_artifact(current_artifact) {
        return assistant_run_static_page_artifact_brief(current_artifact);
    }

    let mut brief = Map::new();
    for key in [
        "type",
        "kind",
        "id",
        "backendId",
        "backend_id",
        "status",
        "title",
        "label",
        "name",
    ] {
        assistant_run_insert_safe_scalar_field(&mut brief, current_artifact, key, key);
    }

    if brief.is_empty() {
        json!({"type": "unknown"})
    } else {
        Value::Object(brief)
    }
}

fn assistant_run_is_static_page_artifact(current_artifact: &Value) -> bool {
    matches!(
        current_artifact
            .get("type")
            .or_else(|| current_artifact.get("kind"))
            .and_then(Value::as_str),
        Some("static_page_draft" | "static_page")
    ) || current_artifact.get("backendDraftId").is_some()
        || current_artifact.get("backend_draft_id").is_some()
        || current_artifact.get("previewContract").is_some()
        || current_artifact.get("preview_contract").is_some()
        || current_artifact.get("finalPage").is_some()
        || current_artifact.get("final_page").is_some()
        || current_artifact.get("previewStale").is_some()
        || current_artifact.get("preview_stale").is_some()
        || (current_artifact.get("modules").is_some()
            && (current_artifact.get("styleDirection").is_some()
                || current_artifact.get("style_direction").is_some()
                || current_artifact.get("previewStatus").is_some()
                || current_artifact.get("preview_status").is_some()
                || current_artifact.get("finalRenderStatus").is_some()
                || current_artifact.get("final_render_status").is_some()))
}

fn assistant_run_static_page_artifact_brief(current_artifact: &Value) -> Value {
    let mut brief = Map::new();
    brief.insert("type".to_string(), json!("static_page_draft"));
    if let Some(id) = static_page_artifact_id(current_artifact) {
        brief.insert("id".to_string(), json!(id));
    }
    if let Some(label) = static_page_artifact_label(current_artifact) {
        brief.insert("label".to_string(), json!(label));
    }
    if let Some(status) = static_page_artifact_string(
        current_artifact,
        &["status", "backendStatus", "backend_status"],
    ) {
        brief.insert("status".to_string(), json!(status));
    }
    if let Some(style_direction) =
        static_page_artifact_string(current_artifact, &["styleDirection", "style_direction"])
    {
        brief.insert("styleDirection".to_string(), json!(style_direction));
    }
    if let Some(preview_status) = static_page_artifact_preview_status(current_artifact) {
        brief.insert("previewStatus".to_string(), json!(preview_status));
    }
    if let Some(final_status) = static_page_artifact_final_status(current_artifact) {
        brief.insert("finalRenderStatus".to_string(), json!(final_status));
    }
    brief.insert(
        "moduleCount".to_string(),
        json!(static_page_artifact_module_count(current_artifact)),
    );
    brief.insert(
        "previewStale".to_string(),
        json!(static_page_artifact_preview_stale(current_artifact)),
    );

    let modules = assistant_run_static_page_module_briefs(current_artifact);
    if !modules.is_empty() {
        brief.insert("modules".to_string(), Value::Array(modules));
    }
    if let Some(binding_quality) = assistant_run_static_page_binding_quality_brief(current_artifact)
    {
        brief.insert("bindingQuality".to_string(), binding_quality);
    }

    Value::Object(brief)
}

fn assistant_run_static_page_binding_quality_brief(current_artifact: &Value) -> Option<Value> {
    let bindings = current_artifact
        .get("dataSnapshot")
        .or_else(|| current_artifact.get("data_snapshot"))
        .and_then(|snapshot| {
            snapshot
                .get("moduleBindings")
                .or_else(|| snapshot.get("module_bindings"))
        })
        .and_then(Value::as_array)?;

    let modules = bindings
        .iter()
        .take(24)
        .map(assistant_run_static_page_binding_quality_module_brief)
        .collect::<Vec<_>>();
    if modules.is_empty() {
        return None;
    }
    let attention_modules = modules
        .iter()
        .filter(|module| {
            module
                .get("bindingQualityStatus")
                .and_then(Value::as_str)
                .is_some_and(|status| status != "confirmed")
                || module
                    .get("chartDataFit")
                    .and_then(Value::as_str)
                    .is_some_and(|fit| matches!(fit, "needs_sample_rows" | "missing_binding"))
        })
        .count();

    Some(json!({
        "moduleCount": modules.len(),
        "attentionModules": attention_modules,
        "policy": "quality_only_no_sample_rows",
        "modules": modules,
    }))
}

fn assistant_run_static_page_binding_quality_module_brief(binding: &Value) -> Value {
    let data_binding = binding
        .get("binding")
        .or_else(|| binding.get("dataBinding"))
        .or_else(|| binding.get("data_binding"))
        .unwrap_or(&Value::Null);
    let binding_quality = binding
        .get("bindingQuality")
        .or_else(|| binding.get("binding_quality"))
        .unwrap_or(&Value::Null);
    json!({
        "moduleId": static_page_artifact_string(binding, &["moduleId", "module_id"]).unwrap_or_default(),
        "title": static_page_artifact_string(binding, &["title"]).unwrap_or_default(),
        "visualizationType": static_page_artifact_string(binding, &["visualizationType", "visualization_type"]).unwrap_or_default(),
        "chartRuntime": static_page_artifact_string(binding, &["chartRuntime", "chart_runtime"]).unwrap_or_default(),
        "dataQuality": static_page_artifact_string(binding, &["dataQuality", "data_quality"]).unwrap_or_default(),
        "bindingQualityStatus": static_page_artifact_string(binding, &["bindingQualityStatus", "binding_quality_status"])
            .or_else(|| static_page_artifact_string(binding_quality, &["status"]))
            .unwrap_or_default(),
        "chartDataFit": static_page_artifact_string(binding, &["chartDataFit", "chart_data_fit"])
            .or_else(|| static_page_artifact_string(binding_quality, &["chartDataFit", "chart_data_fit"]))
            .unwrap_or_default(),
        "reason": static_page_artifact_string(binding_quality, &["reason"]).unwrap_or_default(),
        "recommendedAction": static_page_artifact_string(binding, &["recommendedAction", "recommended_action"])
            .or_else(|| static_page_artifact_string(binding_quality, &["recommendedAction", "recommended_action"]))
            .unwrap_or_default(),
        "sampleRows": binding_quality
            .get("sampleRows")
            .or_else(|| binding_quality.get("sample_rows"))
            .and_then(Value::as_u64)
            .or_else(|| {
                binding
                    .get("sampleData")
                    .or_else(|| binding.get("sample_data"))
                    .and_then(Value::as_array)
                    .map(|items| items.len() as u64)
            })
            .unwrap_or(0),
        "sourceId": static_page_artifact_string(data_binding, &["sourceId", "source_id"]).unwrap_or_default(),
        "fieldPath": static_page_artifact_string(data_binding, &["fieldPath", "field_path", "field"]).unwrap_or_default(),
    })
}

fn assistant_run_static_page_module_briefs(current_artifact: &Value) -> Vec<Value> {
    let Some(modules) = current_artifact.get("modules").and_then(Value::as_array) else {
        return Vec::new();
    };

    modules
        .iter()
        .take(24)
        .enumerate()
        .filter_map(|(index, module)| {
            let mut brief = Map::new();
            brief.insert("index".to_string(), json!(index));
            for key in [
                "id",
                "title",
                "name",
                "type",
                "visualizationType",
                "visualization_type",
                "chartType",
                "chart_type",
                "chartRuntime",
                "chart_runtime",
            ] {
                assistant_run_insert_safe_scalar_field(&mut brief, module, key, key);
            }

            if let Some(visualization) = module.get("visualization") {
                let mut visualization_brief = Map::new();
                assistant_run_insert_safe_scalar_field(
                    &mut visualization_brief,
                    visualization,
                    "type",
                    "type",
                );
                assistant_run_insert_safe_scalar_field(
                    &mut visualization_brief,
                    visualization,
                    "chartRuntime",
                    "chartRuntime",
                );
                assistant_run_insert_safe_scalar_field(
                    &mut visualization_brief,
                    visualization,
                    "chart_runtime",
                    "chart_runtime",
                );
                if !visualization_brief.is_empty() {
                    brief.insert(
                        "visualization".to_string(),
                        Value::Object(visualization_brief),
                    );
                }
            }

            if let Some(data_binding) = module
                .get("dataBinding")
                .or_else(|| module.get("data_binding"))
            {
                let mut data_binding_brief = Map::new();
                for key in [
                    "type",
                    "label",
                    "sourceId",
                    "source_id",
                    "fieldPath",
                    "field_path",
                    "datasetId",
                    "dataset_id",
                ] {
                    assistant_run_insert_safe_scalar_field(
                        &mut data_binding_brief,
                        data_binding,
                        key,
                        key,
                    );
                }
                if !data_binding_brief.is_empty() {
                    brief.insert("dataBinding".to_string(), Value::Object(data_binding_brief));
                }
            }

            if let Some(layout) = module.get("layout").and_then(Value::as_object) {
                let mut layout_brief = Map::new();
                for key in ["x", "y", "w", "h", "minW", "minH", "maxW", "maxH"] {
                    if let Some(value) =
                        layout.get(key).and_then(assistant_run_safe_artifact_scalar)
                    {
                        layout_brief.insert(key.to_string(), value);
                    }
                }
                if !layout_brief.is_empty() {
                    brief.insert("layout".to_string(), Value::Object(layout_brief));
                }
            }

            (brief.len() > 1).then_some(Value::Object(brief))
        })
        .collect()
}

fn assistant_run_insert_safe_scalar_field(
    target: &mut Map<String, Value>,
    source: &Value,
    source_key: &str,
    target_key: &str,
) {
    if let Some(value) = source
        .get(source_key)
        .and_then(assistant_run_safe_artifact_scalar)
    {
        target.insert(target_key.to_string(), value);
    }
}

fn assistant_run_safe_artifact_scalar(value: &Value) -> Option<Value> {
    match value {
        Value::Bool(_) | Value::Number(_) => Some(value.clone()),
        Value::String(text) => Some(json!(truncate_scope_candidate_text(text.trim()))),
        _ => None,
    }
}

fn static_page_artifact_string(artifact: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        artifact
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    })
}

fn static_page_artifact_id(artifact: &Value) -> Option<String> {
    ["backendDraftId", "backend_draft_id", "backendId", "id"]
        .iter()
        .find_map(|key| {
            artifact
                .get(*key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
        })
}

fn static_page_artifact_module_count(artifact: &Value) -> usize {
    ["moduleCount", "module_count"]
        .iter()
        .find_map(|key| artifact.get(*key).and_then(Value::as_u64))
        .map(|value| value as usize)
        .or_else(|| {
            artifact
                .get("modules")
                .and_then(Value::as_array)
                .map(Vec::len)
        })
        .unwrap_or(0)
}

fn static_page_artifact_preview_status(artifact: &Value) -> Option<String> {
    static_page_artifact_string(artifact, &["previewStatus", "preview_status"])
        .or_else(|| {
            artifact
                .get("previewContract")
                .or_else(|| artifact.get("preview_contract"))
                .and_then(|value| value.get("status"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
        })
        .or_else(|| {
            artifact
                .get("imageJob")
                .or_else(|| artifact.get("image_job"))
                .and_then(|value| value.get("status"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
        })
}

fn static_page_artifact_final_status(artifact: &Value) -> Option<String> {
    static_page_artifact_string(artifact, &["finalRenderStatus", "final_render_status"]).or_else(
        || {
            artifact
                .get("finalPage")
                .or_else(|| artifact.get("final_page"))
                .and_then(|value| value.get("status"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
        },
    )
}

fn static_page_artifact_preview_stale(artifact: &Value) -> bool {
    artifact
        .get("previewStale")
        .or_else(|| artifact.get("preview_stale"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || static_page_artifact_preview_status(artifact).as_deref() == Some("stale")
        || artifact
            .get("imageJob")
            .or_else(|| artifact.get("image_job"))
            .and_then(|value| value.get("status"))
            .and_then(Value::as_str)
            == Some("stale")
}

fn static_page_artifact_label(artifact: &Value) -> Option<String> {
    ["objective", "title"].iter().find_map(|key| {
        artifact
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| format!("当前静态页：{}", truncate_scope_candidate_text(value)))
    })
}

fn truncate_scope_candidate_text(value: &str) -> String {
    value.chars().take(80).collect()
}

fn dedupe_assistant_run_scope_candidate_values(candidates: Vec<Value>) -> Vec<Value> {
    let mut seen = HashSet::new();
    candidates
        .into_iter()
        .filter(|candidate| {
            let candidate_type = candidate.get("type").and_then(Value::as_str).unwrap_or("");
            let id = candidate.get("id").and_then(Value::as_str).unwrap_or("");
            if candidate_type.is_empty() || id.is_empty() {
                return true;
            }
            seen.insert(format!("{candidate_type}:{id}"))
        })
        .collect()
}

fn assistant_run_conversation_memory_limit() -> i64 {
    std::env::var("ASSISTANT_RUN_CONVERSATION_MEMORY_LIMIT")
        .ok()
        .and_then(|value| value.parse::<i64>().ok())
        .unwrap_or(ASSISTANT_RUN_CONVERSATION_MEMORY_DEFAULT_LIMIT)
        .clamp(1, ASSISTANT_RUN_CONVERSATION_MEMORY_MAX_LIMIT)
}

fn assistant_run_memory_item_is_supply_eligible(item: &ConversationMemoryItem) -> bool {
    item.role == ChatMessageRole::User
        && !matches!(
            item.item_kind.as_str(),
            "assistant_output" | "artifact_output" | "generated_artifact"
        )
}

fn assistant_run_evidence_supplied_count(evidence_state: &Value) -> usize {
    evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0)
}

fn assistant_run_detail_target_count(evidence_state: &Value) -> usize {
    evidence_state
        .get("detail_targets")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0)
}

fn assistant_run_evidence_status_label(evidence_state: &Value) -> String {
    let status = evidence_state
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    match status {
        "supplied" => {
            let supplied_count = assistant_run_evidence_supplied_count(evidence_state);
            let detail_target_count = assistant_run_detail_target_count(evidence_state);
            let fallback_supply_count = evidence_state
                .get("fallback_supply_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            if fallback_supply_count > 0 {
                if detail_target_count > 0 {
                    return format!(
                        "已供料 {supplied_count} 条，其中 {fallback_supply_count} 条来自可见文档切片兜底，建议深读 {detail_target_count} 份文档"
                    );
                }
                return format!(
                    "已供料 {supplied_count} 条，其中 {fallback_supply_count} 条来自可见文档切片兜底"
                );
            }
            if detail_target_count > 0 {
                format!("已检索 {supplied_count} 条供料项，建议深读 {detail_target_count} 份文档")
            } else {
                format!("已检索 {supplied_count} 条供料项")
            }
        }
        "empty" => "已请求供料，但暂未检索到可用内容".to_string(),
        "not_requested" => "未请求数据集供料".to_string(),
        other => other.to_string(),
    }
}

fn assistant_run_evidence_trail_label(evidence_state: &Value) -> &'static str {
    match evidence_state
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
    {
        "not_requested" => "判断无需数据集供料",
        "empty" => "尝试供料但无结果",
        _ => "检索供料证据",
    }
}

async fn list_chat_messages(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
) -> std::result::Result<Json<Vec<ChatMessageView>>, ApiError> {
    let session_id = parse_chat_session_id(&session_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_chat_session_for_user(
        &state,
        session_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let messages = state
        .storage
        .chat_messages()
        .list_by_session(state.tenant_id, session_id)
        .await
        .map_err(ApiError::from_storage)?;

    let mut views = Vec::with_capacity(messages.len());
    for message in messages {
        views.push(hydrate_chat_message_view(&state, message).await?);
    }

    Ok(Json(views))
}

async fn update_chat_session_report_entry_route(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
    Json(request): Json<UpdateChatSessionReportEntryRequest>,
) -> std::result::Result<(StatusCode, Json<UpdateChatSessionReportEntryResponse>), ApiError> {
    let session_id = parse_chat_session_id(&session_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_chat_session_for_user(
        &state,
        session_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let response = apply_chat_session_report_entry_update_with_state(
        &state,
        session_id,
        current_user_id,
        request,
    )
    .await?;

    Ok((StatusCode::OK, Json(response)))
}

async fn apply_chat_session_report_entry_update_with_state(
    state: &AppState,
    session_id: ChatSessionId,
    current_user_id: Option<UserId>,
    request: UpdateChatSessionReportEntryRequest,
) -> std::result::Result<UpdateChatSessionReportEntryResponse, ApiError> {
    let session = state
        .storage
        .chat_sessions()
        .get_by_id(state.tenant_id, session_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "chat_session_not_found",
                format!("chat session {} was not found", session_id),
            )
        })?;

    let mut session_manifest = session.session_manifest.clone();
    let current_report_entry = parse_chat_session_manifest(&session.session_manifest)
        .and_then(|manifest| manifest.report_entry);
    let now = Utc::now();
    let plan = plan_chat_session_report_entry_update(
        &session,
        current_report_entry.as_ref(),
        &request,
        now,
    )?;

    match plan {
        ChatSessionReportEntryUpdatePlan::RequestConfirmation(entry) => {
            write_chat_session_report_entry(
                &mut session_manifest,
                contracts::ModelFacingReportEntryStateView::ConfirmationRequired,
                &entry,
                None,
                None,
                None,
            )?;

            let updated_session = state
                .storage
                .chat_sessions()
                .update_context(
                    state.tenant_id,
                    session.id,
                    session.latest_memory_directory_id,
                    session.latest_dataset_output_id,
                    &session_manifest,
                    now,
                )
                .await
                .map_err(ApiError::from_storage)?;

            Ok(UpdateChatSessionReportEntryResponse {
                chat_session: hydrate_chat_session_view(state, updated_session).await?,
                report_plan: None,
                workflow_execution: None,
            })
        }
        ChatSessionReportEntryUpdatePlan::StayMaterialService(entry) => {
            write_chat_session_report_entry(
                &mut session_manifest,
                contracts::ModelFacingReportEntryStateView::NotApplicable,
                &entry,
                Some(now),
                Some(contracts::ChatSessionReportEntryResolutionView::StayMaterialService),
                None,
            )?;

            let updated_session = state
                .storage
                .chat_sessions()
                .update_context(
                    state.tenant_id,
                    session.id,
                    session.latest_memory_directory_id,
                    session.latest_dataset_output_id,
                    &session_manifest,
                    now,
                )
                .await
                .map_err(ApiError::from_storage)?;

            Ok(UpdateChatSessionReportEntryResponse {
                chat_session: hydrate_chat_session_view(state, updated_session).await?,
                report_plan: None,
                workflow_execution: None,
            })
        }
        ChatSessionReportEntryUpdatePlan::EnterReportService(entry) => {
            let report_service_handoff = confirmed_report_entry_service_handoff(&entry, now);
            let (plan, execution) = create_report_plan_and_execution(
                state,
                session.dataset_id,
                &entry.title,
                &entry.objective,
                session.user_id.or(current_user_id),
                Some(report_service_handoff),
            )
            .await?;
            write_chat_session_report_entry(
                &mut session_manifest,
                contracts::ModelFacingReportEntryStateView::Confirmed,
                &entry,
                Some(now),
                Some(contracts::ChatSessionReportEntryResolutionView::EnterReportService),
                Some(plan.id),
            )?;

            let updated_session = state
                .storage
                .chat_sessions()
                .update_context(
                    state.tenant_id,
                    session.id,
                    session.latest_memory_directory_id,
                    session.latest_dataset_output_id,
                    &session_manifest,
                    now,
                )
                .await
                .map_err(ApiError::from_storage)?;

            Ok(UpdateChatSessionReportEntryResponse {
                chat_session: hydrate_chat_session_view(state, updated_session).await?,
                report_plan: Some(to_report_plan_summary(
                    plan,
                    workflow_execution_context_service_handoff(&execution),
                )),
                workflow_execution: Some(to_workflow_execution_view(execution)),
            })
        }
    }
}

