async fn list_published_reports(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> std::result::Result<Json<Vec<PublishedReportView>>, ApiError> {
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let local_thread_id = local_thread_id_from_headers(&headers);
    let visible_dataset_ids: HashSet<DatasetId> = filter_visible_datasets(
        state
            .storage
            .datasets()
            .list_by_tenant(state.tenant_id)
            .await
            .map_err(ApiError::from_storage)?,
        &active_secret_binding_ids,
        current_user_id,
        local_thread_id.as_deref(),
    )
    .into_iter()
    .map(|dataset| dataset.id)
    .collect();
    let reports = state
        .storage
        .published_reports()
        .list_by_tenant(state.tenant_id)
        .await
        .map_err(ApiError::from_storage)?;

    let mut views = Vec::with_capacity(reports.len());
    for report in reports {
        if !visible_dataset_ids.contains(&report.dataset_id) {
            continue;
        }
        match load_visible_report_plan_for_user(
            &state,
            report.plan_id,
            &active_secret_binding_ids,
            current_user_id,
        )
        .await
        {
            Ok(_) => views.push(to_published_report_view(report)),
            Err(error) if error.status == StatusCode::NOT_FOUND => continue,
            Err(error) => return Err(error),
        }
    }

    Ok(Json(views))
}

