async fn retry_workflow_execution_with_state(
    state: &AppState,
    execution_id: WorkflowExecutionId,
    request: RetryWorkflowExecutionRequest,
) -> std::result::Result<RetryWorkflowExecutionResponse, ApiError> {
    validate_required("reason", &request.reason)?;

    let retry_transition = apply_workflow_signal(
        state,
        execution_id,
        WorkflowSignal::RetryRequested {
            reason: request.reason.trim().to_string(),
        },
    )
    .await?;
    let restart_transition = if retry_transition.execution.status == WorkflowStatus::Pending {
        Some(apply_workflow_signal(state, execution_id, WorkflowSignal::Start).await?)
    } else {
        None
    };
    sync_static_page_render_output_for_workflow(state, execution_id).await?;

    Ok(RetryWorkflowExecutionResponse {
        retry_transition,
        restart_transition,
    })
}

fn static_page_render_output_status_for_workflow(
    workflow_status: &WorkflowStatus,
    current_status: &StaticPageRenderOutputStatus,
) -> StaticPageRenderOutputStatus {
    match workflow_status {
        WorkflowStatus::Pending => StaticPageRenderOutputStatus::Queued,
        WorkflowStatus::Running => StaticPageRenderOutputStatus::Rendering,
        WorkflowStatus::Failed | WorkflowStatus::DeadLettered => {
            StaticPageRenderOutputStatus::Failed
        }
        WorkflowStatus::Cancelled => StaticPageRenderOutputStatus::Cancelled,
        WorkflowStatus::Succeeded => current_status.clone(),
    }
}

async fn sync_static_page_render_output_for_workflow(
    state: &AppState,
    execution_id: WorkflowExecutionId,
) -> std::result::Result<(), ApiError> {
    let Some(execution) = state
        .storage
        .workflow_executions()
        .get_by_id(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    if execution.kind != WorkflowKind::StaticPageRender {
        return Ok(());
    }
    let Some(output_id) = execution
        .context
        .get("static_page_render_output_id")
        .and_then(Value::as_str)
        .and_then(|raw| Uuid::parse_str(raw).ok())
        .map(domain_model::StaticPageRenderOutputId)
    else {
        return Ok(());
    };
    let Some(mut output) = state
        .storage
        .static_page_render_outputs()
        .get_by_id(state.tenant_id, output_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    let next_status =
        static_page_render_output_status_for_workflow(&execution.status, &output.status);
    if output.status == StaticPageRenderOutputStatus::Rendered
        && !matches!(next_status, StaticPageRenderOutputStatus::Cancelled)
    {
        return Ok(());
    }
    output.status = next_status;
    output.asset_manifest =
        merge_static_page_render_output_workflow_manifest(&output.asset_manifest, &execution);
    state
        .storage
        .static_page_render_outputs()
        .update(state.tenant_id, &output)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(())
}

fn merge_static_page_render_output_workflow_manifest(
    manifest: &Value,
    execution: &WorkflowExecution,
) -> Value {
    let mut object = manifest.as_object().cloned().unwrap_or_default();
    let manifest_status = match execution.status {
        WorkflowStatus::Pending => "queued",
        WorkflowStatus::Running => "rendering",
        WorkflowStatus::Succeeded => "rendered",
        WorkflowStatus::Failed | WorkflowStatus::DeadLettered => "failed",
        WorkflowStatus::Cancelled => "cancelled",
    };
    object.insert("status".to_string(), json!(manifest_status));
    let mut workflow_object = object
        .get("workflow")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    workflow_object.insert("status".to_string(), json!(execution.status.as_str()));
    workflow_object.insert("stage".to_string(), json!(execution.stage));
    workflow_object.insert("executionId".to_string(), json!(execution.id));
    workflow_object.insert("updatedAt".to_string(), json!(execution.updated_at));
    workflow_object.insert(
        "lastError".to_string(),
        execution
            .context
            .get("last_error")
            .cloned()
            .unwrap_or(Value::Null),
    );
    workflow_object.insert(
        "retryReason".to_string(),
        execution
            .context
            .get("retry_reason")
            .cloned()
            .unwrap_or(Value::Null),
    );
    workflow_object.insert(
        "cancelReason".to_string(),
        execution
            .context
            .get("cancel_reason")
            .cloned()
            .unwrap_or(Value::Null),
    );
    object.insert("workflow".to_string(), Value::Object(workflow_object));
    Value::Object(object)
}

async fn apply_workflow_signal(
    state: &AppState,
    execution_id: WorkflowExecutionId,
    signal: WorkflowSignal,
) -> std::result::Result<AdvanceWorkflowExecutionResponse, ApiError> {
    apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        execution_id,
        signal,
    )
    .await
}

pub async fn apply_workflow_signal_with_dependencies(
    storage: &PgStorage,
    workflow_catalog: &WorkflowCatalog,
    event_bus: &EventBus,
    tenant_id: TenantId,
    execution_id: WorkflowExecutionId,
    signal: WorkflowSignal,
) -> std::result::Result<AdvanceWorkflowExecutionResponse, ApiError> {
    let execution = storage
        .workflow_executions()
        .get_by_id(tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "workflow_execution_not_found",
                format!("workflow execution {} was not found", execution_id),
            )
        })?;

    let definition = workflow_catalog
        .find_definition(execution.kind.clone())
        .ok_or_else(|| {
            ApiError::internal(
                "workflow_definition_missing",
                format!(
                    "workflow definition {} is not registered",
                    execution.kind.as_str()
                ),
            )
        })?;
    let now = Utc::now();
    let runtime_state = workflow_runtime_state_from_execution(&execution)?;
    let transition = definition
        .transition(&runtime_state, signal, now)
        .map_err(ApiError::from_transition)?;
    let workflow_engine::WorkflowTransition {
        next_state,
        persisted_event,
        enqueued_tasks,
    } = transition;
    let next_execution = workflow_execution_from_transition(&execution, next_state)?;
    let pending_tasks: Vec<NewWorkflowTask> = enqueued_tasks
        .into_iter()
        .map(|task| NewWorkflowTask {
            queue: task.queue,
            task_key: task.task_key,
            payload: task.payload,
            available_at: persisted_event.occurred_at,
            max_attempts: 3,
        })
        .collect();
    let (persisted_event, persisted_tasks) = storage
        .workflow_executions()
        .advance_with_tasks(
            &next_execution,
            &persisted_event.name,
            &persisted_event.detail,
            persisted_event.occurred_at,
            &pending_tasks,
        )
        .await
        .map_err(ApiError::from_storage)?;
    publish_workflow_transition_events(
        event_bus,
        &next_execution,
        &persisted_event,
        &persisted_tasks,
    )
    .await;

    Ok(AdvanceWorkflowExecutionResponse {
        execution: to_workflow_execution_view(next_execution),
        persisted_event: to_workflow_event_view(persisted_event),
        enqueued_tasks: persisted_tasks
            .into_iter()
            .map(to_workflow_task_view)
            .collect(),
    })
}

async fn publish_workflow_transition_events(
    event_bus: &EventBus,
    execution: &WorkflowExecution,
    persisted_event: &WorkflowEventRecord,
    persisted_tasks: &[WorkflowTask],
) {
    let execution_event = EventEnvelope {
        subject: workflow_execution_transition_subject(execution.kind.as_str()),
        payload: json!({
            "execution_id": execution.id,
            "tenant_id": execution.tenant_id,
            "kind": execution.kind.as_str(),
            "status": execution.status.as_str(),
            "stage": execution.stage,
            "event_name": persisted_event.event_name,
            "event_sequence_no": persisted_event.sequence_no,
        }),
        published_at: persisted_event.created_at,
    };
    event_bus.publish(execution_event).await;

    for task in persisted_tasks {
        let task_event = EventEnvelope {
            subject: workflow_task_enqueued_subject(&task.queue, &task.task_key),
            payload: json!({
                "task_id": task.id,
                "tenant_id": task.tenant_id,
                "execution_id": task.execution_id,
                "queue": task.queue,
                "task_key": task.task_key,
                "status": task.status.as_str(),
                "available_at": task.available_at,
            }),
            published_at: task.created_at,
        };
        event_bus.publish(task_event).await;
    }
}

fn build_initial_report_plan_execution(
    state: &AppState,
    plan: &ReportPlan,
    service_handoff: Option<&contracts::ManifestServiceHandoffView>,
) -> std::result::Result<WorkflowExecution, ApiError> {
    let definition = state
        .workflow_catalog
        .find_definition(WorkflowKind::ReportPlan)
        .ok_or_else(|| {
            ApiError::internal(
                "workflow_definition_missing",
                "report_plan workflow definition is not registered".to_string(),
            )
        })?;
    let now = Utc::now();
    let execution_id = WorkflowExecutionId::new();
    let runtime_state = definition.initial_state(execution_id, now);
    let mut context = runtime_state.context;
    context.insert(
        "retries_remaining".to_string(),
        Value::Number(runtime_state.retries_remaining.into()),
    );
    if let Some(service_handoff) = service_handoff {
        context.insert("service_handoff".to_string(), json!(service_handoff));
    }

    Ok(WorkflowExecution {
        id: execution_id,
        tenant_id: state.tenant_id,
        dataset_id: Some(plan.dataset_id),
        report_plan_id: Some(plan.id),
        kind: WorkflowKind::ReportPlan,
        version: runtime_state.version,
        stage: runtime_state.stage,
        status: runtime_state.status,
        attempt: 0,
        context: Value::Object(context),
        created_at: now,
        updated_at: now,
    })
}

