    #[test]
    fn static_page_preview_gate_blocks_unrenderable_chart_bindings() {
        let now = Utc::now();
        let draft = StaticPageDraft {
            id: StaticPageDraftId::new(),
            tenant_id: TenantId::new(),
            owner_user_id: None,
            assistant_run_id: AssistantRunId::new(),
            title: "经营分析静态页".to_string(),
            status: StaticPageDraftStatus::Planned,
            selected_scope: json!({
                "mode": "user_selected",
                "datasets": [DatasetId::new().to_string()],
            }),
            visibility_snapshot: json!({"policy": "test"}),
            source_refs: Value::Null,
            draft_payload: json!({
                "version": 1,
                "status": "planning",
                "modules": [{
                    "id": "trend",
                    "title": "订单趋势",
                    "dataBinding": {
                        "sourceId": "dataset",
                        "fieldPath": "dataset.metrics_summary",
                        "label": "订单金额"
                    },
                    "visualization": {
                        "type": "line-chart",
                        "chartOptions": {
                            "dataKey": "dataset.metrics_summary"
                        }
                    }
                }]
            }),
            created_at: now,
            updated_at: now,
        };

        let (reason, details) = static_page_preview_data_quality_gate_for_draft(&draft)
            .expect("chart without sample rows should be blocked");

        assert!(reason.contains("订单趋势"));
        assert!(reason.contains("needs_sample_rows"));
        assert!(reason.contains("补充样本行"));
        assert!(details["attentionModules"][0]["gateReasons"]
            .as_array()
            .expect("gate reasons")
            .contains(&json!("chart_data_fit:needs_sample_rows")));
        assert_eq!(
            details["gateReasonCounts"]["chart_sample_rows_missing"],
            json!(1)
        );
    }

