    async fn post_json_request<T: serde::Serialize>(
        app: Router,
        uri: &str,
        payload: &T,
        cookie: Option<&str>,
    ) -> axum::response::Response {
        let mut builder = axum::http::Request::builder()
            .method("POST")
            .uri(uri)
            .header(axum::http::header::CONTENT_TYPE, "application/json");
        if let Some(cookie) = cookie {
            builder = builder.header(axum::http::header::COOKIE, cookie);
        }
        let request = builder
            .body(axum::body::Body::from(
                serde_json::to_vec(payload).expect("request should serialize"),
            ))
            .expect("request should build");

        app.oneshot(request)
            .await
            .expect("request should return a response")
    }

    async fn get_request(app: Router, uri: &str, cookie: Option<&str>) -> axum::response::Response {
        let mut builder = axum::http::Request::builder().method("GET").uri(uri);
        if let Some(cookie) = cookie {
            builder = builder.header(axum::http::header::COOKIE, cookie);
        }
        let request = builder
            .body(axum::body::Body::empty())
            .expect("request should build");

        app.oneshot(request)
            .await
            .expect("request should return a response")
    }

    async fn get_request_with_local_thread(
        app: Router,
        uri: &str,
        cookie: Option<&str>,
        local_thread_id: &str,
    ) -> axum::response::Response {
        let mut builder = axum::http::Request::builder()
            .method("GET")
            .uri(uri)
            .header(LOCAL_THREAD_ID_HEADER, local_thread_id);
        if let Some(cookie) = cookie {
            builder = builder.header(axum::http::header::COOKIE, cookie);
        }
        let request = builder
            .body(axum::body::Body::empty())
            .expect("request should build");

        app.oneshot(request)
            .await
            .expect("request should return a response")
    }

    fn cookie_pair_from_set_cookie(response: &axum::response::Response) -> String {
        response
            .headers()
            .get(axum::http::header::SET_COOKIE)
            .expect("set-cookie should be present")
            .to_str()
            .expect("set-cookie should be utf-8")
            .split(';')
            .next()
            .expect("set-cookie should contain pair")
            .to_string()
    }

