    #[test]
    fn rank_document_chunks_for_prompt_prefers_cjk_phrase_overlap_for_fallback_supply() {
        let now = Utc::now();
        let tenant_id = TenantId::new();
        let dataset_id = DatasetId::new();
        let broad_document_id = DocumentId::new();
        let phrase_document_id = DocumentId::new();
        let broad_chunk_id = DocumentChunkId::new();
        let phrase_chunk_id = DocumentChunkId::new();

        let broad_document = Document {
            id: broad_document_id,
            tenant_id,
            dataset_id,
            owner_user_id: None,
            title: "客服记录".to_string(),
            object_key: "documents/support.md".to_string(),
            content_type: "text/markdown".to_string(),
            lifecycle: domain_model::DocumentLifecycle::Extracted,
            secret_binding_ids: Vec::new(),
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };
        let phrase_document = Document {
            id: phrase_document_id,
            tenant_id,
            dataset_id,
            owner_user_id: None,
            title: "订单延期风险".to_string(),
            object_key: "documents/orders.md".to_string(),
            content_type: "text/markdown".to_string(),
            lifecycle: domain_model::DocumentLifecycle::Extracted,
            secret_binding_ids: Vec::new(),
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };
        let broad_chunk = DocumentChunk {
            id: broad_chunk_id,
            tenant_id,
            dataset_id,
            document_id: broad_document_id,
            chunk_index: 0,
            content: "订单和风险分别出现在客服记录中，主要讨论满意度。".to_string(),
            token_count: 12,
            state: DocumentChunkState::Extracted,
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };
        let phrase_chunk = DocumentChunk {
            id: phrase_chunk_id,
            tenant_id,
            dataset_id,
            document_id: phrase_document_id,
            chunk_index: 1,
            content: "订单延期风险集中在仓库交接，超过两天需要赔付提醒。".to_string(),
            token_count: 16,
            state: DocumentChunkState::Extracted,
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };

        let ranked = rank_document_chunks_for_prompt(
            vec![
                (broad_document, broad_chunk),
                (phrase_document, phrase_chunk),
            ],
            "订单延期风险",
            2,
        );

        assert_eq!(ranked[0].chunk.id, phrase_chunk_id);
        assert_eq!(ranked[1].chunk.id, broad_chunk_id);
        assert!(ranked[0].lexical_score > ranked[1].lexical_score);
        assert!(ranked[0].search_text.contains("订单延期风险"));
    }

    #[test]
    fn to_report_render_output_view_exposes_typed_status() {
        let now = Utc::now();
        let output = ReportRenderOutput {
            id: ReportRenderOutputId::new(),
            tenant_id: TenantId::new(),
            execution_id: WorkflowExecutionId::new(),
            plan_id: ReportPlanId::new(),
            dataset_id: DatasetId::new(),
            ast_version_id: ReportPlanAstVersionId::new(),
            surface: PublishedSurface::Mobile,
            status: ReportRenderOutputStatus::Rendered,
            asset_manifest: json!({
                "kind": "placeholder_asset",
                "path": "reports/demo/mobile.html",
            }),
            created_at: now,
        };

        let view = to_report_render_output_view(output, None);

        assert_eq!(view.surface, PublishedSurface::Mobile);
        assert_eq!(
            view.status,
            contracts::ReportRenderOutputStatusView::Rendered
        );
        assert_eq!(view.asset_manifest["kind"], json!("placeholder_asset"));
        assert_eq!(
            view.model_facing
                .as_ref()
                .map(|model| &model.capability_class),
            Some(&contracts::ModelFacingCapabilityClassView::ReportGenerationAndEditing)
        );
        assert_eq!(
            view.model_facing.as_ref().map(|model| &model.service_lane),
            Some(&contracts::ModelFacingServiceLaneView::ReportService)
        );
        assert_eq!(
            view.model_facing
                .as_ref()
                .map(|model| &model.report_entry_state),
            Some(&contracts::ModelFacingReportEntryStateView::Confirmed)
        );
        assert_eq!(
            view.model_facing
                .as_ref()
                .map(|model| &model.evidence_state),
            Some(&contracts::ModelFacingEvidenceStateView::Mixed)
        );
        assert_eq!(
            view.model_facing
                .as_ref()
                .map(|model| &model.continuation_state),
            Some(&contracts::ModelFacingContinuationStateView::NeedsPlatformContinuation)
        );
        assert_eq!(
            view.model_facing
                .as_ref()
                .and_then(|model| model.recommended_next_action.clone()),
            Some(contracts::ModelFacingNextActionView::PublishReport)
        );
        assert!(view
            .model_facing
            .as_ref()
            .expect("report render output should expose model_facing summary")
            .allowed_next_actions
            .contains(&contracts::ModelFacingNextActionView::PublishReport));
        assert!(!view
            .model_facing
            .as_ref()
            .expect("report render output should expose model_facing summary")
            .allowed_next_actions
            .contains(&contracts::ModelFacingNextActionView::GenerateReportOutput));
        assert_eq!(
            view.model_facing
                .as_ref()
                .and_then(|model| model.recommended_tool_key.clone()),
            Some("report.publish".to_string())
        );
        assert!(view
            .model_facing
            .as_ref()
            .expect("report render output should expose model_facing summary")
            .allowed_tool_keys
            .contains(&"report.publish".to_string()));
    }

